-- 011: доимпорт услуг сети «XXI Век», пропущенных в 008.
-- В stand/services.json у 545 услуг клиника не определилась по прайсам PDF (clinics: []),
-- поэтому 008 их не импортировала. Клиника назначается так:
--   1. стационарные услуги -> «21 Век на Северном» (стационар по прайсу);
--   2. иначе -> клиники сети, где работают врачи того же направления (med_field);
--   3. если таких врачей нет -> обе клиники сети.
-- Дубли по названию (КТ/МРТ-служебные, проктология амб./стац.) схлопнуты, у операций — стационарный вариант.
-- Идемпотентно: услуга с тем же названием, уже привязанная к клинике сети, пропускается.

BEGIN;


CREATE TEMP TABLE _new_services (
  name TEXT PRIMARY KEY, direction TEXT, price NUMERIC, price_from BOOLEAN,
  stationary BOOLEAN, self_booking BOOLEAN, at_doctor_visit BOOLEAN
) ON COMMIT DROP;


CREATE TEMP TABLE _net_clinics ON COMMIT DROP AS
SELECT c.id, c.name FROM clinics c
JOIN clinic_nets n ON n.id = c.clinic_net_id
WHERE n.name = 'XXI Век';

-- Отбрасываем уже импортированные
DELETE FROM _new_services ns
WHERE EXISTS (
  SELECT 1 FROM services s
  JOIN services_by_clinics sbc ON sbc.service_id = s.id
  WHERE s.name = ns.name AND sbc.clinic_id IN (SELECT id FROM _net_clinics)
);

CREATE TEMP TABLE _inserted ON COMMIT DROP AS
WITH ins AS (
  SELECT ns.name, mf.id, ns.stationary, ns.self_booking, ns.at_doctor_visit, ns.price_from
  FROM _new_services ns
  JOIN med_fields mf ON mf.name = ns.direction
  RETURNING id, name, med_field_id, stationary
)
SELECT * FROM ins;

-- Клиники сети, где работают врачи направления
CREATE TEMP TABLE _field_clinics ON COMMIT DROP AS
SELECT DISTINCT sp.med_field_id, dl.clinic_id
FROM doctors d
JOIN specialities sp ON sp.id = d.speciality_id
JOIN doctor_locations dl ON dl.doctor_id = d.id
WHERE dl.clinic_id IN (SELECT id FROM _net_clinics);

SELECT i.id, c.id, ns.price
FROM _inserted i
JOIN _new_services ns ON ns.name = i.name
JOIN _net_clinics c ON
  CASE
    WHEN i.stationary THEN c.name = '21 Век на Северном'
    WHEN EXISTS (SELECT 1 FROM _field_clinics fc WHERE fc.med_field_id = i.med_field_id)
      THEN c.id IN (SELECT fc.clinic_id FROM _field_clinics fc WHERE fc.med_field_id = i.med_field_id)
    ELSE true
  END;

COMMIT;
